-- provider ---------------------------------------------------------------
insert into ops.provider (provider_code, provider_name, provider_kind, homepage_url)
values ('dataforseo', 'DataForSEO', 'serp_ai_api', 'https://dataforseo.com/')
on conflict (provider_code) do nothing;

-- provider_profile (4) ---------------------------------------------------
insert into manifest.provider_profile (methodology_version_id, surface_id, provider_id, profile_code,
  method, post_endpoint, get_endpoint, language_code, device, operating_system, location_mode,
  location_template, result_depth, priority, max_tasks_per_post, settings, settings_sha256)
select mv.methodology_version_id, s.surface_id, p.provider_id, v.profile_code, v.method,
  v.post_endpoint, v.get_endpoint, v.language_code, v.device, v.os, v.location_mode,
  v.location_template, v.result_depth, v.priority, v.max_tasks_per_post, v.settings, v.settings_sha256
from (values
  ('maps', 'DFS_MAPS_V1', 'standard_async', '/v3/serp/google/maps/task_post', '/v3/serp/google/maps/task_get/advanced/{id}', 'en', 'desktop', 'windows', 'location_coordinate', '{lat},{lon},17z', 10, 1, 100, '{"depth": 10, "device": "desktop", "get_endpoint": "/v3/serp/google/maps/task_get/advanced/{id}", "language_code": "en", "location_coordinate": "{lat},{lon},17z", "max_tasks_per_post": 100, "method": "standard_async", "os": "windows", "post_endpoint": "/v3/serp/google/maps/task_post", "priority": 1, "search_places": false, "search_this_area": true}'::jsonb, '9b126981fce6d7ac789f22614e56ec2e538511f8cd098e33a9bce6005a651bc7'),
  ('organic', 'DFS_ORGANIC_V1', 'standard_async', '/v3/serp/google/organic/task_post', '/v3/serp/google/organic/task_get/advanced/{id}', 'en', 'desktop', 'windows', 'location_coordinate', '{lat},{lon},200', 10, 1, 100, '{"depth": 10, "device": "desktop", "get_endpoint": "/v3/serp/google/organic/task_get/advanced/{id}", "language_code": "en", "load_async_ai_overview": false, "location_coordinate": "{lat},{lon},200", "max_tasks_per_post": 100, "method": "standard_async", "os": "windows", "post_endpoint": "/v3/serp/google/organic/task_post", "priority": 1}'::jsonb, '87814d39aac82ca987a8e2f09fe30eac5612ac4074251ce1883fdc4c900a1665'),
  ('aio', 'DFS_AIO_V1', 'standard_async', '/v3/serp/google/ai_mode/task_post', '/v3/serp/google/ai_mode/task_get/advanced/{id}', 'en', 'desktop', 'windows', 'location_coordinate', '{lat},{lon},9z', null, 1, 100, '{"calculate_rectangles": false, "device": "desktop", "get_endpoint": "/v3/serp/google/ai_mode/task_get/advanced/{id}", "language_code": "en", "location_coordinate": "{lat},{lon},9z", "max_tasks_per_post": 100, "method": "standard_async", "os": "windows", "post_endpoint": "/v3/serp/google/ai_mode/task_post", "priority": 1}'::jsonb, 'eac21a3f98ce52a812b8548ff69dde22c66b8883a7c8602ac127b66f1bc05c65'),
  ('chatgpt', 'DFS_CHATGPT_V1', 'standard_async', '/v3/ai_optimization/chat_gpt/llm_scraper/task_post', '/v3/ai_optimization/chat_gpt/llm_scraper/task_get/advanced/{id}', 'en', null, null, 'location_code', '2840', null, 1, 100, '{"get_endpoint": "/v3/ai_optimization/chat_gpt/llm_scraper/task_get/advanced/{id}", "language_code": "en", "location_code": 2840, "market_in_prompt_only": true, "max_tasks_per_post": 100, "method": "standard_async", "post_endpoint": "/v3/ai_optimization/chat_gpt/llm_scraper/task_post", "priority": 1, "replicate_timing": "independent tasks co-submitted in same wave batch when practical", "replicates": 3, "shared_context": false}'::jsonb, 'cd168e6e71a77790f2037af34ebe3c601de41aa175acc349327ee099a3c3b991')
) as v(surface_code, profile_code, method, post_endpoint, get_endpoint, language_code, device, os,
       location_mode, location_template, result_depth, priority, max_tasks_per_post, settings, settings_sha256)
join manifest.surface s on s.surface_code = v.surface_code
cross join ops.provider p
join manifest.methodology_version mv on mv.methodology_code = 'MANIFEST_V1_0'
where p.provider_code = 'dataforseo'
on conflict (methodology_version_id, profile_code) do nothing;

-- surface_config (4) -----------------------------------------------------
insert into manifest.surface_config (methodology_version_id, surface_id, provider_profile_id,
  geometry_version_id, full_panel_cadence, sentinel_cadence, replicates, result_depth, raw_response_required)
select mv.methodology_version_id, s.surface_id, pp.provider_profile_id,
  gv.geometry_version_id, 'monthly', 'weekly', v.replicates, v.result_depth, true
from (values
  ('maps', 'DFS_MAPS_V1', 'MAPORG13_V1', 1, 10),
  ('organic', 'DFS_ORGANIC_V1', 'MAPORG13_V1', 1, 10),
  ('aio', 'DFS_AIO_V1', 'AIO9_V1', 1, null),
  ('chatgpt', 'DFS_CHATGPT_V1', null, 3, null)
) as v(surface_code, profile_code, geometry_code, replicates, result_depth)
join manifest.surface s on s.surface_code = v.surface_code
join manifest.methodology_version mv on mv.methodology_code = 'MANIFEST_V1_0'
join manifest.provider_profile pp on pp.methodology_version_id = mv.methodology_version_id and pp.profile_code = v.profile_code
left join manifest.geometry_version gv on gv.methodology_version_id = mv.methodology_version_id and gv.geometry_code = v.geometry_code
on conflict (methodology_version_id, surface_id) do nothing;

-- panel_subset: fixed weekly Sentinel (5 industries x 10 markets) --------
insert into manifest.panel_subset (methodology_version_id, subset_code, subset_kind, fixed_membership, description)
select mv.methodology_version_id, 'SENTINEL_V1', 'sentinel', true,
  'Fixed weekly Research Sentinel: 5 industries x 10 markets (monthly wave doubles as that week''s Sentinel).'
from manifest.methodology_version mv where mv.methodology_code = 'MANIFEST_V1_0'
on conflict (methodology_version_id, subset_code) do nothing;

insert into manifest.panel_subset_industry (panel_subset_id, industry_id, ordinal)
select ps.panel_subset_id, i.industry_id, v.ordinal
from (values
  ('IND001', 1),
  ('IND010', 2),
  ('IND011', 3),
  ('IND019', 4),
  ('IND022', 5)
) as v(industry_code, ordinal)
join manifest.industry i on i.industry_code = v.industry_code
join manifest.methodology_version mv on mv.methodology_code = 'MANIFEST_V1_0'
join manifest.panel_subset ps on ps.methodology_version_id = mv.methodology_version_id and ps.subset_code = 'SENTINEL_V1'
on conflict do nothing;

insert into manifest.panel_subset_market (panel_subset_id, market_id, ordinal)
select ps.panel_subset_id, mk.market_id, v.ordinal
from (values
  ('MKT001', 1),
  ('MKT008', 2),
  ('MKT011', 3),
  ('MKT016', 4),
  ('MKT021', 5),
  ('MKT024', 6),
  ('MKT031', 7),
  ('MKT037', 8),
  ('MKT041', 9),
  ('MKT050', 10)
) as v(market_code, ordinal)
join manifest.market mk on mk.market_code = v.market_code
join manifest.methodology_version mv on mv.methodology_code = 'MANIFEST_V1_0'
join manifest.panel_subset ps on ps.methodology_version_id = mv.methodology_version_id and ps.subset_code = 'SENTINEL_V1'
on conflict do nothing;

